INDEX_HTML = '<!doctype html>\n<html lang="ru">\n<head>\n<meta charset="utf-8">\n<meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover,interactive-widget=resizes-content">\n<meta name="color-scheme" content="light">\n<meta name="theme-color" content="#f1f0e9">\n<title>ЗарницаКлаб — CRM</title>\n<script src="https://telegram.org/js/telegram-web-app.js"></script>\n<link rel="stylesheet" href="/static/style.css">\n</head>\n<body>\n<main class="app">\n\n  <!-- Стартовый экран -->\n  <section id="screen-start" class="screen screen-start">\n    <header class="start-header">\n      <div class="brand">ЗАРНИЦАКЛАБ</div>\n      <h1 class="start-title">CRM</h1>\n      <div class="start-sub">mini app</div>\n    </header>\n    <div class="start-grid">\n      <button class="start-btn" data-go="schedule"><span class="start-ico">📅</span><span>Расписание</span></button>\n      <button class="start-btn" data-go="clients"><span class="start-ico">👥</span><span>Клиенты</span></button>\n      <button class="start-btn" data-go="orders"><span class="start-ico">📋</span><span>Заказы</span></button>\n      <button class="start-btn" data-go="calls"><span class="start-ico">📞</span><span>Звонки</span></button>\n      <button class="start-btn start-btn-wide" data-go="bso"><span class="start-ico">🧾</span><span>БСО</span></button>\n    </div>\n  </section>\n\n  <!-- Экран «Расписание» -->\n  <section id="screen-schedule" class="screen" hidden>\n    <header class="screen-header">\n      <div class="header-row">\n        <div>\n          <div class="brand">ЗАРНИЦАКЛАБ</div>\n          <h1>Расписание</h1>\n        </div>\n        <div class="weekend">\n          <div class="weekend-label">Ожидаем в выходные</div>\n          <div class="weekend-value">👥 <span id="weekendCount">—</span></div>\n        </div>\n      </div>\n    </header>\n\n    <div class="period-row">\n      <div class="month-nav">\n        <button class="month-arrow" id="prevMonth" aria-label="Предыдущий месяц">‹</button>\n        <button class="month-label" id="monthLabel">—</button>\n        <button class="month-arrow" id="nextMonth" aria-label="Следующий месяц">›</button>\n      </div>\n      <button class="icon-btn" id="filterBtn" title="Фильтры">☷</button>\n      <button class="cta-btn" id="newRecordBtn">＋ Новая запись</button>\n    </div>\n\n    <div class="week" id="weekStrip"></div>\n\n    <div class="day-info" id="dayInfo"></div>\n\n    <section id="scheduleList" class="schedule-list"></section>\n  </section>\n\n  <!-- Экран «Клиенты» -->\n  <section id="screen-clients" class="screen" hidden>\n    <header class="screen-header">\n      <div class="brand">ЗАРНИЦАКЛАБ</div>\n      <h1>Клиенты</h1>\n    </header>\n    <div id="clientsSummary" class="summary">Загрузка…</div>\n    <section id="clientsList" class="orders"></section>\n  </section>\n\n  <!-- Экран «Заказы» -->\n  <section id="screen-orders" class="screen" hidden>\n    <header class="screen-header">\n      <div class="brand">ЗАРНИЦАКЛАБ</div>\n      <h1>Заказы</h1>\n    </header>\n    <div class="filter-row" id="ordersFilterRow">\n      <button class="chip active" data-ofilter="recent">Ближайшие</button>\n      <button class="chip" data-ofilter="date">Найти по дате</button>\n    </div>\n    <div id="ordersCalendar" class="cal-wrap" hidden></div>\n    <div id="ordersSummary" class="summary">Загрузка…</div>\n    <section id="ordersList" class="orders"></section>\n  </section>\n\n  <!-- Экран «Звонки» -->\n  <section id="screen-calls" class="screen" hidden>\n    <header class="screen-header">\n      <div class="brand">ЗАРНИЦАКЛАБ</div>\n      <h1>Звонки</h1>\n    </header>\n    <div id="callsDateStrip" class="day-strip-wrap"></div>\n    <div id="callsSummary" class="summary">Загрузка…</div>\n    <section id="callsTodayList" class="orders"></section>\n  </section>\n\n  <!-- Экран «БСО» -->\n  <section id="screen-bso" class="screen" hidden>\n    <header class="screen-header">\n      <div class="brand">ЗАРНИЦАКЛАБ</div>\n      <h1>БСО</h1>\n    </header>\n    <div class="filter-row" id="bsoFilterRow">\n      <button class="chip active" data-bsofilter="all">Все</button>\n      <button class="chip" data-bsofilter="date">Выбор даты</button>\n    </div>\n    <div id="bsoDateStrip" class="day-strip-wrap" hidden></div>\n    <div id="bsoSummary" class="summary">Загрузка…</div>\n    <section id="bsoList" class="orders"></section>\n  </section>\n\n  <!-- Нижняя навигация (появляется на внутренних экранах) -->\n  <nav class="bottom-nav" id="bottomNav" hidden>\n    <button class="nav-item" data-go="schedule"><span class="nav-ico">📅</span><span>Расписание</span></button>\n    <button class="nav-item" data-go="orders"><span class="nav-ico">📋</span><span>Заказы</span></button>\n    <button class="nav-item" data-go="calls"><span class="nav-ico">📞</span><span>Звонки</span></button>\n    <button class="nav-item" id="navMore" type="button"><span class="nav-ico">•••</span><span>ЕЩЕ</span></button>\n  </nav>\n\n  <div class="more-menu" id="moreMenu" hidden>\n    <button class="more-item" data-go="clients"><span class="more-ico">👥</span><span>Клиенты</span></button>\n    <button class="more-item" data-go="bso"><span class="more-ico">🧾</span><span>БСО</span></button>\n  </div>\n\n</main>\n\n<dialog id="orderDialog">\n  <div class="dialog-body">\n    <button class="close" id="closeDialog">×</button>\n    <div id="detail"></div>\n  </div>\n</dialog>\n\n<script src="/static/app.js"></script>\n</body>\n</html>\n'

APP_JS = 'const tg = window.Telegram?.WebApp;\nif (tg) { tg.ready(); tg.expand(); }\n\nfunction authHeaders() {\n  return {"X-Telegram-Init-Data": (window.Telegram?.WebApp?.initData) || ""};\n}\n\nconst state = {\n  orders: [],\n  clients: [],\n  bso: [],\n  view: "start",\n  ordersFilter: "recent",\n  ordersMonth: null,\n  ordersDate: null,\n  selectedDate: null,\n  callsDate: null,\n  bsoFilter: "all",\n  bsoDate: null,\n};\n\nconst dialog = document.getElementById("orderDialog");\nconst detailEl = document.getElementById("detail");\n\nconst VIEW_SECTIONS = {\n  start: "screen-start",\n  schedule: "screen-schedule",\n  clients: "screen-clients",\n  orders: "screen-orders",\n  calls: "screen-calls",\n  bso: "screen-bso",\n};\n\nconst MONTHS_RU = ["Январь","Февраль","Март","Апрель","Май","Июнь","Июль","Август","Сентябрь","Октябрь","Ноябрь","Декабрь"];\nconst MONTHS_GEN = ["января","февраля","марта","апреля","мая","июня","июля","августа","сентября","октября","ноября","декабря"];\nconst WEEKDAYS_RU = ["Вс","Пн","Вт","Ср","Чт","Пт","Сб"];\n\n/* ---------- утилиты ---------- */\n\nfunction esc(v) {\n  return String(v ?? "").replace(/[&<>"\']/g, c => ({\n    "&":"&amp;","<":"&lt;",">":"&gt;",\'"\':"&quot;","\'":"&#039;"\n  }[c]));\n}\n\nfunction paid(o) {\n  return String(o.status || "").toLowerCase() === "paid";\n}\n\nfunction statusOrAmount(o) {\n  if (paid(o) && o.payment?.amount != null) return rub(o);\n  return String(o.status || "—");\n}\n\nfunction sessionLabel(session) {\n  const s = String(session || "").trim().replace(/^[-\\s–—•]+/, "").replace(/[\\s;.]+$/, "");\n  if (!s) return "—";\n  return s.replace(/\\s+с\\s+/i, " · с ");\n}\n\nfunction rub(o) {\n  if (o.payment?.amount == null) return "—";\n  return Number(o.payment.amount).toLocaleString("ru-RU") + " ₽";\n}\n\nfunction fmtMoney(n) {\n  const num = Number(n);\n  if (n == null || isNaN(num)) return "—";\n  return num.toLocaleString("ru-RU", {maximumFractionDigits: 2}) + " ₽";\n}\n\nfunction normPhone(v) {\n  const d = String(v || "").replace(/\\D/g, "");\n  if (d.length === 10 && d[0] === "9") return "7" + d;\n  if (d.length === 11 && d[0] === "8") return "7" + d.slice(1);\n  return d;\n}\n\nfunction phoneLink(v) {\n  const p = normPhone(v);\n  return p ? "+" + p : "";\n}\n\nfunction phonePretty(v) {\n  const p = normPhone(v);\n  if (p.length === 11 && p[0] === "7") {\n    return `+7 (${p.slice(1, 4)}) ${p.slice(4, 7)}-${p.slice(7, 9)}-${p.slice(9, 11)}`;\n  }\n  return phoneLink(v);\n}\n\n/* --- время поступления: в базе UTC, показываем и группируем по Москве --- */\nconst MSK_OFFSET_MS = 3 * 3600 * 1000;\n\nfunction parseTs(value) {\n  if (!value) return null;\n  const s = String(value).trim().replace(" ", "T");\n  const d = new Date(/(Z|[+-]\\d{2}(?::?\\d{2})?)$/.test(s) ? s : s + "Z");\n  return isNaN(d.getTime()) ? null : d;\n}\n\nfunction mskDate(value) {\n  const d = parseTs(value);\n  if (!d) return "";\n  return new Date(d.getTime() + MSK_OFFSET_MS).toISOString().slice(0, 10);\n}\n\nfunction formatReceivedAt(value) {\n  if (!value) return "";\n  const d = parseTs(value);\n  if (!d) return String(value);\n  const s = new Date(d.getTime() + MSK_OFFSET_MS);\n  const p = n => String(n).padStart(2, "0");\n  return `${p(s.getUTCDate())}.${p(s.getUTCMonth() + 1)}.${String(s.getUTCFullYear()).slice(-2)} · ${p(s.getUTCHours())}:${p(s.getUTCMinutes())}`;\n}\n\nfunction formatCallDatetime(value) {\n  if (!value) return "";\n  // Время звонка показываем по Москве (как и «Поступило»), а не по часам телефона:\n  // иначе на чужом устройстве время в скопированном отчёте «уезжает».\n  const d = parseTs(value);\n  if (!d) return formatReceivedAt(value);\n  const p = n => String(n).padStart(2, "0");\n  const s = new Date(d.getTime() + MSK_OFFSET_MS);\n  return `${p(s.getUTCDate())}.${p(s.getUTCMonth() + 1)}.${String(s.getUTCFullYear()).slice(-2)} · ${p(s.getUTCHours())}:${p(s.getUTCMinutes())}`;\n}\n\nfunction formatEventDate(value) {\n  if (!value) return "";\n  const text = String(value);\n  const iso = text.match(/^(\\d{4})-(\\d{2})-(\\d{2})/);\n  if (iso) return `${iso[3]}.${iso[2]}.${iso[1]}`;\n  return text;\n}\n\n/* ---------- заказы: порядок и фильтр по дате поступления оплаты ---------- */\n\nfunction receiptTime(o) {\n  const d = parseTs(o?.received_at);\n  return d ? d.getTime() : 0;\n}\n\nfunction sortByReceipt(list) {\n  return [...list].sort((a, b) => {\n    const ta = receiptTime(a), tb = receiptTime(b);\n    if (ta !== tb) return tb - ta; // новые сверху\n    return String(b.order_id).localeCompare(String(a.order_id));\n  });\n}\n\nfunction receiptDays() {\n  const set = new Set();\n  state.orders.forEach(o => { const d = mskDate(o.received_at); if (d) set.add(d); });\n  return [...set].sort().reverse(); // свежие слева\n}\n\nfunction latestReceiptDay() {\n  return receiptDays()[0] || "";\n}\n\nfunction formatReceiptDay(iso) {\n  const m = String(iso || "").match(/^(\\d{4})-(\\d{2})-(\\d{2})/);\n  if (!m) return String(iso || "");\n  const d = new Date(+m[1], +m[2] - 1, +m[3]);\n  return `${m[3]}.${m[2]}.${m[1]}, ${WEEKDAYS_RU[d.getDay()]}`;\n}\n\n\n\n/* ---------- классификация игры / сеанса (дизайн, без БД) ---------- */\n\nfunction gameClass(game) {\n  const g = String(game || "").toLowerCase();\n  if (g.includes("пейнтбол")) return "paintball";\n  if (g.includes("лазер")) return "lasertag";\n  if (g.includes("кидбол")) return "kidball";\n  return "other";\n}\n\nfunction sessionInfo(session) {\n  const s = String(session || "").toLowerCase();\n  if (s.includes("утренн")) return { period: "Утро", time: "09:00–14:45" };\n  if (s.includes("вечерн")) return { period: "Вечер", time: "15:15–21:00" };\n  return { period: "Сеанс", time: session || "—" };\n}\n\n/* ---------- даты ---------- */\n\nfunction pad2(n) { return String(n).padStart(2, "0"); }\n\nfunction isoDate(d) {\n  return `${d.getFullYear()}-${pad2(d.getMonth() + 1)}-${pad2(d.getDate())}`;\n}\n\nfunction mondayOf(d) {\n  const x = new Date(d.getFullYear(), d.getMonth(), d.getDate());\n  const dow = (x.getDay() + 6) % 7; // 0 = Пн … 6 = Вс\n  x.setDate(x.getDate() - dow);\n  return x;\n}\n\nfunction addDays(d, n) {\n  const x = new Date(d);\n  x.setDate(x.getDate() + n);\n  return x;\n}\n\nfunction fmtDayLong(d) {\n  return `${WEEKDAYS_RU[d.getDay()]}, ${d.getDate()} ${MONTHS_GEN[d.getMonth()]}`;\n}\n\n/* ---------- фильтр-полоса дат (ползунок) ---------- */\n\nfunction renderDayStrip(containerEl, selectedIso, onChange, opts) {\n  const o = opts || {};\n  const allowAll = !!o.allowAll;\n  const today = new Date();\n  today.setHours(0, 0, 0, 0);\n  let html = \'<div class="day-strip">\';\n  if (allowAll) {\n    const activeAll = selectedIso == null || selectedIso === "";\n    html += `<button class="day-chip all${activeAll ? " active" : ""}" data-date="">Все</button>`;\n  }\n  for (let i = -30; i <= 7; i++) {\n    const day = addDays(today, i);\n    const ds = isoDate(day);\n    const active = ds === selectedIso;\n    const isToday = ds === isoDate(today);\n    html += `\n      <button class="day-chip${active ? " active" : ""}${isToday ? " today" : ""}" data-date="${ds}">\n        <span class="day-chip-dow">${WEEKDAYS_RU[day.getDay()]}</span>\n        <span class="day-chip-num">${day.getDate()}</span>\n      </button>`;\n  }\n  html += \'</div>\';\n  containerEl.innerHTML = html;\n  containerEl.querySelectorAll(".day-chip").forEach(btn => {\n    btn.addEventListener("click", () => onChange(btn.dataset.date));\n  });\n  const sel = containerEl.querySelector(".day-chip.active");\n  if (sel) sel.scrollIntoView({ inline: "center", block: "nearest" });\n}\n\nfunction ordersOn(dateStr) {\n  return state.orders.filter(o => o.event?.date && String(o.event.date).slice(0, 10) === dateStr);\n}\n\nfunction dayHasOrders(dateStr) {\n  return state.orders.some(o => o.event?.date && String(o.event.date).slice(0, 10) === dateStr);\n}\n\nfunction sortOrders(list) {\n  const rank = o => {\n    const s = String(o.event?.session || "").toLowerCase();\n    if (s.includes("утренн")) return 0;\n    if (s.includes("вечерн")) return 1;\n    return 2;\n  };\n  return [...list].sort((a, b) => {\n    const r = rank(a) - rank(b);\n    if (r) return r;\n    return String(a.event?.session || "").localeCompare(String(b.event?.session || ""), "ru");\n  });\n}\n\n/* ---------- звонки ---------- */\n\nfunction findClientByPhone(phone) {\n  const p = normPhone(phone);\n  if (!p) return null;\n  return state.clients.find(c => normPhone(c.phone) === p) || null;\n}\n\nfunction orderForCall(call) {\n  if (!call.order_id) return null;\n  return state.orders.find(o => String(o.order_id) === String(call.order_id)) || null;\n}\n\nfunction callClientInfo(call) {\n  const order = orderForCall(call);\n  const client = (order && findClientByPhone(order.customer?.phone)) || findClientByPhone(call.phone);\n  const name = (order?.customer?.name) || (client?.name) || "";\n  return { order, client, name };\n}\n\n/* Подписи и цвета плашек с типом запроса: теги ставит calls_tagger по расшифровке записи. */\nconst CALL_TAG_LABEL = {\n  "детский": "Детский",\n  "школьная_группа": "Школьная группа",\n  "корпоратив": "Корпоратив",\n  "праздник_взрослые": "Праздник, взрослые",\n  "просто_игра": "Просто игра",\n  "нецелевой": "Нецелевой",\n  "непонятно": "Непонятно",\n};\nconst CALL_TAG_CLASS = {\n  "детский": "kids",\n  "школьная_группа": "school",\n  "корпоратив": "corp",\n  "праздник_взрослые": "party",\n  "просто_игра": "game",\n  "нецелевой": "junk",\n  "непонятно": "unknown",\n};\n\nfunction callTagLabel(type) {\n  return CALL_TAG_LABEL[type] || type || "";\n}\n\n/* Плашка «Детский · 📅 17.10.2026 · 👥 30». Нет тега (старый звонок, ещё не размечен) — пусто. */\nfunction callTagsHtml(call) {\n  const tags = call.tags || {};\n  if (!tags.type) return "";\n  const bits = [];\n  if (tags.date && tags.date.date) {\n    bits.push(`<span class="call-tag-meta">📅 ${esc(formatEventDate(tags.date.date))}</span>`);\n  }\n  if (tags.players && tags.players.players) {\n    bits.push(`<span class="call-tag-meta">👥 ${esc(tags.players.players)}</span>`);\n  }\n  const cls = CALL_TAG_CLASS[tags.type] || "unknown";\n  return `<div class="call-tags"><span class="call-tag tag-${cls}">${esc(callTagLabel(tags.type))}</span>${bits.join("")}</div>`;\n}\n\nfunction callCard(call, options) {\n  const opts = (options && typeof options === "object") ? options : {};\n  const duration = Number(call.duration_seconds || 0);\n  const mm = Math.floor(duration / 60);\n  const ss = String(duration % 60).padStart(2, "0");\n  const dt = formatCallDatetime(call.call_datetime);\n  const showClient = Boolean(opts.showClient);\n  const linked = showClient && Boolean(call.order_id);\n  const info = showClient ? callClientInfo(call) : null;\n  const clientName = linked && info ? info.name : "";\n  const idxAttr = opts.index != null ? ` data-call-index="${opts.index}"` : "";\n  return `\n    <article class="call-card${linked ? " call-card-linked" : ""}"${idxAttr}>\n      ${callTagsHtml(call)}\n      <div class="call-topline">\n        <div class="call-date">📞 ${esc(dt || "Дата не указана")}</div>\n        <div class="call-duration">${mm}:${ss}</div>\n      </div>\n      ${clientName ? `<div class="call-client">👤 ${esc(clientName)}</div>` : ""}\n      <div class="call-admin">${esc(call.administrator || "Администратор не указан")}</div>\n      <div class="call-phone">${esc(call.phone || "")}</div>\n      ${call.audio_url ? `<audio class="call-audio" controls preload="none" src="${esc(call.audio_url)}"></audio>\n      <button class="call-link" type="button" data-audio-link="${esc(permanentAudioLink(call.audio_url))}">🔗 Ссылка на запись</button>` : `<div class="call-unavailable">MP3 недоступен</div>`}\n    </article>\n  `;\n}\n\n/* ---------- записи звонков: громкость 50 % и постоянная ссылка на хранилище ---------- */\n\nconst CALL_VOLUME = 0.5; // по просьбе Артёма: запись играет вдвое тише\nlet callAudioCtx = null;\nconst callGainWired = new WeakSet();\n\n/* Постоянная ссылка на файл: у presigned-ссылки отрезаем «?X-Amz-…» — бакет хранилища\n   публичный, без подписи файл отдаётся всегда (проверено 09.10.2026). */\nfunction permanentAudioLink(url) {\n  return String(url || "").split("?")[0];\n}\n\n/* Громкость. На Android и ПК достаточно HTMLMediaElement.volume; на iPhone это свойство\n   не работает (громкость — только кнопками телефона), поэтому там звук идёт через GainNode. */\nfunction setCallVolume(el) {\n  if (!el) return;\n  try { el.volume = CALL_VOLUME; } catch (e) { /* свойство может быть только для чтения */ }\n  if (Math.abs(Number(el.volume) - CALL_VOLUME) < 0.01) return;\n  wireGainVolume(el);\n}\n\nfunction wireGainVolume(el) {\n  if (callGainWired.has(el)) return;\n  const Ctx = window.AudioContext || window.webkitAudioContext;\n  if (!Ctx) return;\n  try {\n    if (!callAudioCtx) callAudioCtx = new Ctx();\n    const source = callAudioCtx.createMediaElementSource(el);\n    const gain = callAudioCtx.createGain();\n    gain.gain.value = CALL_VOLUME;\n    source.connect(gain);\n    gain.connect(callAudioCtx.destination);\n    callGainWired.add(el);\n    const resume = () => {\n      if (callAudioCtx && callAudioCtx.state === "suspended") callAudioCtx.resume().catch(() => {});\n    };\n    el.addEventListener("play", resume);\n    el.addEventListener("click", resume);\n    resume();\n  } catch (e) { /* не получилось — пусть играет как есть, но не молчит */ }\n}\n\n/* Лёгкий отчёт по звонку: копируется вместе с постоянной ссылкой на запись. */\nfunction callReportText(call) {\n  const duration = Number(call.duration_seconds || 0);\n  const mm = Math.floor(duration / 60);\n  const ss = String(duration % 60).padStart(2, "0");\n  const info = callClientInfo(call);\n  const dt = formatCallDatetime(call.call_datetime);\n  const lines = [`Звонок в клуб${dt ? " " + dt : ""} (${mm}:${ss})`];\n  const tags = call.tags || {};\n  if (tags.type) lines.push(`Тип: ${callTagLabel(tags.type).toLowerCase()}`);\n  if (tags.date && tags.date.date) lines.push(`Дата игры: ${formatEventDate(tags.date.date)}`);\n  if (tags.players && tags.players.players) lines.push(`Игроков: ${tags.players.players}`);\n  const phone = call.phone || info.order?.customer?.phone || "";\n  const who = [info.name, phone ? phonePretty(phone) : ""].filter(Boolean).join(", ");\n  if (who) lines.push(`Клиент: ${who}`);\n  if (call.administrator) lines.push(`Принял: ${call.administrator}`);\n  if (info.order) {\n    const parts = [];\n    if (info.order.event?.game) parts.push(String(info.order.event.game));\n    if (info.order.event?.date) parts.push(formatEventDate(info.order.event.date));\n    if (info.order.event?.qty) parts.push(`${info.order.event.qty} чел.`);\n    lines.push(`Заказ ${info.order.order_id}${parts.length ? ": " + parts.join(", ") : ""}`);\n  }\n  lines.push(`Запись: ${permanentAudioLink(call.audio_url)}`);\n  return lines.join("\\n");\n}\n\n/* Плеер и кнопка ссылки внутри карточки звонка: гасим всплытие, чтобы на экране «Звонки»\n   нажатие на запись не открывало заодно карточку клиента. */\nfunction initCallCards(root, calls) {\n  if (!root) return;\n  root.querySelectorAll("audio.call-audio").forEach(el => {\n    setCallVolume(el);\n    ["click", "pointerdown", "mousedown", "touchstart"].forEach(ev =>\n      el.addEventListener(ev, e => e.stopPropagation()));\n  });\n  root.querySelectorAll(".call-card").forEach(card => {\n    const btn = card.querySelector("[data-audio-link]");\n    if (!btn) return;\n    const call = (calls && calls[Number(card.dataset.callIndex)]) || null;\n    const text = call ? callReportText(call) : permanentAudioLink(btn.dataset.audioLink);\n    btn.addEventListener("click", e => {\n      e.stopPropagation();\n      copyText(text, btn);\n    });\n  });\n}\n\nlet copyToastTimer = null;\n\nfunction showCopyToast(text) {\n  let el = document.getElementById("copyToast");\n  if (!el) {\n    el = document.createElement("div");\n    el.id = "copyToast";\n    el.className = "copy-toast";\n    document.body.appendChild(el);\n  }\n  el.textContent = text;\n  el.classList.add("on");\n  clearTimeout(copyToastTimer);\n  copyToastTimer = setTimeout(() => el.classList.remove("on"), 1400);\n}\n\nasync function copyText(text, btn) {\n  try {\n    if (navigator.clipboard && window.isSecureContext) {\n      await navigator.clipboard.writeText(text);\n    } else {\n      const ta = document.createElement("textarea");\n      ta.value = text;\n      ta.setAttribute("readonly", "");\n      ta.style.position = "fixed";\n      ta.style.opacity = "0";\n      document.body.appendChild(ta);\n      ta.select();\n      document.execCommand("copy");\n      ta.remove();\n    }\n    if (btn) {\n      if (btn.tagName === "BUTTON" || btn.tagName === "A") {\n        if (!btn.dataset.oldText) btn.dataset.oldText = btn.textContent;\n        btn.textContent = "✓ Скопировано";\n        clearTimeout(btn._copyTimer);\n        btn._copyTimer = setTimeout(() => { btn.textContent = btn.dataset.oldText; }, 1500);\n      } else {\n        showCopyToast("Скопировано: " + text);\n      }\n    }\n  } catch (e) {\n    // буфер обмена недоступен — оставляем как есть\n  }\n}\n\nfunction wireCopyButtons() {\n  detailEl.querySelectorAll("[data-copy]").forEach(btn => {\n    btn.addEventListener("click", () => copyText(btn.dataset.copy, btn));\n    if (btn.tagName !== "BUTTON" && btn.tagName !== "A") {\n      btn.setAttribute("role", "button");\n      btn.setAttribute("tabindex", "0");\n      btn.addEventListener("keydown", e => {\n        if (e.key === "Enter" || e.key === " ") {\n          e.preventDefault();\n          copyText(btn.dataset.copy, btn);\n        }\n      });\n    }\n  });\n}\n\n/* ---------- карточки ---------- */\n\nfunction scheduleCard(o) {\n  const cls = gameClass(o.event?.game);\n  const si = sessionInfo(o.event?.session);\n  const qty = o.event?.qty ? `${esc(o.event.qty)} чел.` : "";\n  const name = esc(o.customer?.name || "Без имени");\n  const price = rub(o);\n  const phone = normPhone(o.customer?.phone);\n  return `\n    <article class="sch-card card-${cls}" data-id="${esc(o.order_id)}">\n      <div class="sch-row1">\n        <span class="sch-period">${esc(si.period)}</span>\n        <span class="sch-game">${esc(o.event?.game || "Игра не указана")}</span>\n        <span class="sch-price">${price}</span>\n      </div>\n      <div class="sch-row2">\n        <span class="sch-qty">${qty}</span>\n        <span class="sch-name">${name}</span>\n        ${phone ? `<a class="sch-phone" href="tel:${esc(phoneLink(o.customer.phone))}">📞</a>` : ""}\n      </div>\n      <div class="sch-row3">${esc(si.time)} · ${esc(statusOrAmount(o))}</div>\n    </article>\n  `;\n}\n\nfunction orderCard(o) {\n  return `\n    <article class="card" data-id="${esc(o.order_id)}">\n      <div class="topline">\n        <div class="date">📅 ${esc(formatEventDate(o.event?.date) || "Дата не указана")}</div>\n        <div class="${paid(o) && o.payment?.amount != null ? "sum-pill" : "status"}">${esc(statusOrAmount(o))}</div>\n      </div>\n      <div class="card-mainline">\n        <div class="name">${esc(o.customer?.name || "Без имени")}</div>\n        ${o.event?.qty ? `<div class="players-count">👥 <span>${esc(o.event.qty)}</span></div>` : ""}\n      </div>\n      <div class="meta">\n        🕒 ${esc(o.event?.session ? sessionLabel(o.event.session) : "Сеанс не указан")}\n      </div>\n      ${o.event?.game ? `<div class="game">🎯 ${esc(o.event.game)}</div>` : ""}\n      ${o.event?.tent ? `<div class="meta">🏕 ${esc(o.event.tent)}</div>` : ""}\n      ${o.received_at ? `<div class="received-at">Поступило: ${esc(formatReceivedAt(o.received_at))}</div>` : ""}\n    </article>\n  `;\n}\n\n/* ---------- детали ---------- */\n\n/* БСО в карточке заказа: появляется сам, когда бланк уже заведён */\nasync function loadOrderBso(orderId) {\n  const slot = document.getElementById("orderBsoSlot");\n  if (!slot) return;\n  try {\n    const r = await fetch(`/api/orders/${encodeURIComponent(orderId)}/bso`, {cache: "no-store", headers: authHeaders()});\n    if (!r.ok) return;\n    const b = (await r.json()).bso;\n    if (!b) return;\n    slot.hidden = false;\n    slot.innerHTML = `\n      <div class="calls-heading">БСО</div>\n      <div class="bso-inline">\n        <div class="bso-inline-head">\n          <span class="bso-inline-num">БСО № ${esc(b.bso_number || "—")}</span>\n          <span class="bso-inline-sum">${fmtMoney(b.order_amount)}</span>\n        </div>\n        <div class="bso-row"><span>Факт игроков</span><span>${esc(b.players_fact ?? "—")}</span></div>\n        <div class="bso-row"><span>Зона отдыха</span><span>${fmtMoney(b.rest_zone_amount)}</span></div>\n        <div class="bso-row"><span>Дата игры</span><span>${esc(formatEventDate(b.game_date) || "—")}</span></div>\n      </div>`;\n  } catch (e) { /* нет данных — блок не показываем */ }\n}\n\nasync function openOrder(o) {\n  if (!state.clients.length) {\n    await loadClientsData().catch(() => {});\n  }\n  const phone = normPhone(o.customer?.phone);\n  const client = phone ? state.clients.find(c => normPhone(c.phone) === phone) : null;\n  if (client) { openClientCard(client.client_id); }\n  else { openDetail(o); }\n}\n\nasync function openDetail(o) {\n  const c = o.customer || {};\n  const e = o.event || {};\n  const p = o.payment || {};\n  const sum = paid(o) && p.amount != null ? rub(o) : "";\n\n  detailEl.innerHTML = `\n    <div class="detail-title">${esc(c.name || "Заказ")}</div>\n    <div class="detail-subtitle">Карточка заказа</div>\n    <div class="detail-status">\n      ${sum ? `<span class="amount-pill">${esc(sum)}</span>` : `<span class="status">${esc(o.status || "—")}</span>`}\n      ${p.transaction_id ? `<span class="txn-id">Номер транзакции ${esc(p.transaction_id)}</span>` : ""}\n    </div>\n\n    <div class="key-block">\n      <div>\n        <div class="key-label">Дата</div>\n        <div class="key-value">${esc(formatEventDate(e.date) || "—")}</div>\n      </div>\n      <div>\n        <div class="key-label">Сеанс</div>\n        <div class="key-value">${esc(sessionLabel(e.session))}</div>\n      </div>\n      ${e.qty ? `<div>\n        <div class="key-label">Игроков</div>\n        <div class="key-qty">${esc(e.qty)}</div>\n      </div>` : ""}\n      <div>\n        <div class="key-label">Тариф</div>\n        <div class="key-value">${esc(e.game || "—")}</div>\n      </div>\n    </div>\n\n    <div class="grid">\n      <div class="item item-copy" data-copy="${esc(o.order_id)}"><div class="label">Заказ</div><div class="value">${esc(o.order_id)}</div></div>\n      <div class="item"><div class="label">Размещение</div><div class="value">${esc(e.tent || "—")}</div></div>\n    </div>\n\n    <div class="actions">\n      ${c.phone ? `<button class="action" type="button" data-copy="${esc(phoneLink(c.phone))}">📞 ${esc(phonePretty(c.phone))}</button>` : ""}\n      ${c.email ? `<button class="action action-ghost" type="button" data-copy="${esc(c.email)}">✉️ ${esc(c.email)}</button>` : ""}\n    </div>\n\n    <section class="bso-in-order" id="orderBsoSlot" hidden></section>\n\n    <section class="calls-section">\n      <div class="calls-heading">Звонки</div>\n      <div id="callsList" class="calls-list"><div class="empty">Загрузка звонков…</div></div>\n    </section>\n  `;\n  dialog.showModal();\n  wireCopyButtons();\n  loadOrderBso(o.order_id);\n\n  try {\n    const r = await fetch(`/api/orders/${encodeURIComponent(o.order_id)}/calls`, {cache:"no-store", headers: authHeaders()});\n    if (!r.ok) throw new Error("HTTP " + r.status);\n    const data = await r.json();\n    const calls = data.calls || [];\n    const list = document.getElementById("callsList");\n    if (!calls.length) {\n      list.innerHTML = `<div class="empty">Звонков пока нет</div>`;\n      return;\n    }\n    list.innerHTML = calls.map((c, i) => callCard(c, { index: i })).join("");\n    initCallCards(list, calls);\n  } catch (err) {\n    const list = document.getElementById("callsList");\n    if (list) list.innerHTML = `<div class="empty">Не удалось загрузить звонки: ${esc(err.message)}</div>`;\n  }\n}\n\nasync function openClientCard(clientId) {\n  const client = state.clients.find(c => String(c.client_id) === String(clientId));\n  if (!client) {\n    detailEl.innerHTML = `<div class="detail-title">Клиент не найден</div>`;\n    dialog.showModal();\n    return;\n  }\n\n  const phone = normPhone(client.phone);\n  const orders = state.orders\n    .filter(o => phone && normPhone(o.customer?.phone) === phone)\n    .sort((a, b) => String(b.event?.date || "").localeCompare(String(a.event?.date || "")));\n\n  detailEl.innerHTML = `\n    <div class="detail-title">${esc(client.name || "Без имени")}${client.client_id != null ? `<span class="client-id">#${esc(client.client_id)}</span>` : ""}</div>\n    <div class="detail-subtitle">Карточка клиента</div>\n\n    <div class="actions">\n      ${client.phone ? `<button class="action" type="button" data-copy="${esc(phoneLink(client.phone))}">📞 ${esc(phonePretty(client.phone))}</button>` : ""}\n      ${client.email ? `<button class="action" type="button" data-copy="${esc(client.email)}">✉️ ${esc(client.email)}</button>` : ""}\n    </div>\n\n    <section class="calls-section">\n      <div class="calls-heading">Заказы (${orders.length})</div>\n      <div id="clientOrders" class="orders-mini"></div>\n    </section>\n\n    <section class="calls-section">\n      <div class="calls-heading">Звонки</div>\n      <div id="callsList" class="calls-list"><div class="empty">Загрузка звонков…</div></div>\n    </section>\n  `;\n  dialog.showModal();\n  wireCopyButtons();\n\n  const ordersBox = document.getElementById("clientOrders");\n  if (orders.length) {\n    ordersBox.innerHTML = orders.map(o => `\n      <article class="order-mini" data-id="${esc(o.order_id)}">\n        <div class="order-mini-top">\n          <span class="order-mini-id">${esc(o.order_id)}</span>\n          <span class="order-mini-date">${esc(formatEventDate(o.event?.date) || "—")}</span>\n        </div>\n      </article>\n    `).join("");\n    ordersBox.querySelectorAll(".order-mini").forEach(el => {\n      el.addEventListener("click", () => {\n        const o = state.orders.find(x => String(x.order_id) === el.dataset.id);\n        if (o) openDetail(o);\n      });\n    });\n  } else {\n    ordersBox.innerHTML = `<div class="empty">Заказов нет</div>`;\n  }\n\n  try {\n    const r = await fetch(`/api/clients/${encodeURIComponent(clientId)}/calls`, {cache:"no-store", headers: authHeaders()});\n    if (!r.ok) throw new Error("HTTP " + r.status);\n    const data = await r.json();\n    const calls = data.calls || [];\n    const list = document.getElementById("callsList");\n    if (!calls.length) { list.innerHTML = `<div class="empty">Звонков нет</div>`; return; }\n    list.innerHTML = calls.map((c, i) => callCard(c, { index: i })).join("");\n    initCallCards(list, calls);\n  } catch (err) {\n    const list = document.getElementById("callsList");\n    if (list) list.innerHTML = `<div class="empty">Не удалось загрузить звонки: ${esc(err.message)}</div>`;\n  }\n}\n\n/* ---------- экран «Расписание» ---------- */\n\n/* склонение числительных: 1 игра / 2 игры / 6 игр */\nfunction plural(n, one, few, many) {\n  const n10 = n % 10, n100 = n % 100;\n  if (n10 === 1 && n100 !== 11) return one;\n  if (n10 >= 2 && n10 <= 4 && (n100 < 12 || n100 > 14)) return few;\n  return many;\n}\n\nfunction renderWeek(d) {\n  const mon = mondayOf(d);\n  const sel = isoDate(d);\n  const strip = document.getElementById("weekStrip");\n  let html = `<button class="week-arrow" data-shift="-7" aria-label="Предыдущая неделя">‹</button>`;\n  for (let i = 0; i < 7; i++) {\n    const day = addDays(mon, i);\n    const ds = isoDate(day);\n    const has = dayHasOrders(ds);\n    const active = ds === sel;\n    const today = ds === isoDate(new Date());\n    html += `\n      <button class="week-day${active ? " active" : ""}${today ? " today" : ""}" data-date="${ds}">\n        <span class="week-dow">${WEEKDAYS_RU[day.getDay()]}</span>\n        <span class="week-num">${day.getDate()}</span>\n        <span class="week-dot${has ? " has" : ""}">${has ? "●" : ""}</span>\n      </button>`;\n  }\n  html += `<button class="week-arrow" data-shift="7" aria-label="Следующая неделя">›</button>`;\n  strip.innerHTML = html;\n\n  strip.querySelectorAll(".week-day").forEach(btn => {\n    btn.addEventListener("click", () => selectDay(btn.dataset.date));\n  });\n  strip.querySelectorAll(".week-arrow").forEach(btn => {\n    btn.addEventListener("click", () => {\n      state.selectedDate = addDays(state.selectedDate || new Date(), Number(btn.dataset.shift));\n      renderSchedule();\n    });\n  });\n}\n\nfunction selectDay(dateStr) {\n  const [y, m, dd] = dateStr.split("-").map(Number);\n  state.selectedDate = new Date(y, m - 1, dd);\n  renderSchedule();\n}\n\nfunction shiftMonth(delta) {\n  const d = state.selectedDate || new Date();\n  const target = new Date(d.getFullYear(), d.getMonth() + delta, 1);\n  const lastDay = new Date(target.getFullYear(), target.getMonth() + 1, 0).getDate();\n  const day = Math.min(d.getDate(), lastDay);\n  state.selectedDate = new Date(target.getFullYear(), target.getMonth(), day);\n  renderSchedule();\n}\n\nfunction renderSchedule() {\n  const d = state.selectedDate || new Date();\n\n  document.getElementById("monthLabel").textContent = `${MONTHS_RU[d.getMonth()]} ${d.getFullYear()}`;\n  renderWeek(d);\n\n  const dayInfo = document.getElementById("dayInfo");\n  const dayList = ordersOn(isoDate(d));\n  const games = dayList.length;\n  const people = dayList.reduce((sum, o) => {\n    const n = parseInt(String(o.event?.qty ?? "").trim(), 10);\n    return sum + (Number.isFinite(n) ? n : 0);\n  }, 0);\n  dayInfo.innerHTML = games ? `\n    <div class="day-info-title">${esc(fmtDayLong(d))}</div>\n    <div class="day-stats">\n      <div class="day-stat"><span class="day-stat-ico">🎯</span><span class="day-stat-num">${games}</span><span class="day-stat-cap">${plural(games, "игра", "игры", "игр")}</span></div>\n      <div class="day-stat"><span class="day-stat-ico">👥</span><span class="day-stat-num">${people}</span><span class="day-stat-cap">${plural(people, "человек", "человека", "человек")}</span></div>\n    </div>\n  ` : `\n    <div class="day-info-title">${esc(fmtDayLong(d))}</div>\n    <div class="day-info-body">На этот день записей нет</div>\n  `;\n\n  const list = sortOrders(dayList);\n  const box = document.getElementById("scheduleList");\n  if (!list.length) {\n    box.innerHTML = `<div class="empty">На этот день записей нет</div>`;\n    return;\n  }\n  box.innerHTML = list.map(scheduleCard).join("");\n  box.querySelectorAll(".sch-card").forEach(card => {\n    card.addEventListener("click", () => {\n      const o = state.orders.find(x => String(x.order_id) === card.dataset.id);\n      if (o) openDetail(o);\n    });\n  });\n}\n\n/* ---------- экраны «Заказы» / «Клиенты» / «Звонки» ---------- */\n\nconst CAL_DOW = ["Пн", "Вт", "Ср", "Чт", "Пт", "Сб", "Вс"];\n\nfunction todayMsk() {\n  return mskDate(new Date().toISOString());\n}\n\nfunction monthKeyOf(iso) {\n  return String(iso || "").slice(0, 7);\n}\n\nfunction monthTitle(mk) {\n  const parts = String(mk || "").split("-");\n  if (parts.length < 2) return String(mk || "");\n  return `${MONTHS_RU[Number(parts[1]) - 1]} ${parts[0]}`;\n}\n\nfunction receiptCounts() {\n  const counts = {};\n  state.orders.forEach(o => {\n    const d = mskDate(o.received_at);\n    if (d) counts[d] = (counts[d] || 0) + 1;\n  });\n  return counts;\n}\n\nfunction receiptDates(list) {\n  const set = new Set();\n  list.forEach(o => { const d = mskDate(o.received_at); if (d) set.add(d); });\n  return [...set].sort().reverse();\n}\n\nfunction renderOrdersCalendar() {\n  const wrap = document.getElementById("ordersCalendar");\n  if (!wrap) return;\n  if (state.ordersFilter !== "date") {\n    wrap.hidden = true;\n    return;\n  }\n  wrap.hidden = false;\n  if (!state.ordersMonth) state.ordersMonth = monthKeyOf(latestReceiptDay() || todayMsk());\n\n  const parts = state.ordersMonth.split("-").map(Number);\n  const year = parts[0], month = parts[1];\n  const firstDow = (new Date(year, month - 1, 1).getDay() + 6) % 7; // неделя с понедельника\n  const daysInMonth = new Date(year, month, 0).getDate();\n  const counts = receiptCounts();\n  const todayIso = todayMsk();\n\n  let cells = "";\n  for (let i = 0; i < firstDow; i++) cells += \'<span class="cal-day off empty"></span>\';\n  for (let day = 1; day <= daysInMonth; day++) {\n    const ds = `${year}-${String(month).padStart(2, "0")}-${String(day).padStart(2, "0")}`;\n    const n = counts[ds] || 0;\n    const cls = ["cal-day"];\n    if (!n) cls.push("off");\n    if (ds === state.ordersDate) cls.push("active");\n    if (ds === todayIso) cls.push("today");\n    cells += `<button class="${cls.join(" ")}"${n ? ` data-date="${ds}"` : " disabled"}><span class="cal-num">${day}</span><span class="cal-dot${n ? " has" : ""}"></span></button>`;\n  }\n\n  const canNext = state.ordersMonth < monthKeyOf(todayMsk());\n  wrap.innerHTML = `\n    <div class="cal-head">\n      <button class="month-arrow" data-cal="prev" aria-label="Предыдущий месяц">\\u2039</button>\n      <div class="month-label">${esc(monthTitle(state.ordersMonth))}</div>\n      <button class="month-arrow" data-cal="next" aria-label="Следующий месяц"${canNext ? "" : " disabled"}>\\u203A</button>\n    </div>\n    <div class="cal-dow">${CAL_DOW.map(t => `<span>${t}</span>`).join("")}</div>\n    <div class="cal-grid">${cells}</div>`;\n\n  wrap.querySelector(\'[data-cal="prev"]\').addEventListener("click", () => shiftOrdersMonth(-1));\n  const next = wrap.querySelector(\'[data-cal="next"]\');\n  if (next && !next.disabled) next.addEventListener("click", () => shiftOrdersMonth(1));\n  wrap.querySelectorAll(".cal-day[data-date]").forEach(btn => {\n    btn.addEventListener("click", () => {\n      state.ordersDate = btn.dataset.date;\n      renderOrders();\n    });\n  });\n}\n\nfunction shiftOrdersMonth(delta) {\n  const parts = String(state.ordersMonth || "").split("-").map(Number);\n  const d = new Date(parts[0], parts[1] - 1 + delta, 1);\n  const mk = `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}`;\n  if (mk > monthKeyOf(todayMsk())) return; // вперёд не листаем: оплату вперёд не получают\n  state.ordersMonth = mk;\n  // Только календарь: renderOrders() заново выставил бы месяц по выбранной дате и стрелка бы «не нажалась».\n  renderOrdersCalendar();\n}\n\nfunction renderOrders() {\n  const box = document.getElementById("ordersList");\n  const summary = document.getElementById("ordersSummary");\n  let list = sortByReceipt(state.orders);\n  let summaryText = "";\n\n  if (state.ordersFilter === "date") {\n    const days = receiptDates(state.orders);\n    if (!state.ordersDate || days.indexOf(state.ordersDate) === -1) state.ordersDate = days[0] || "";\n    state.ordersMonth = monthKeyOf(state.ordersDate) || state.ordersMonth;\n    list = list.filter(o => mskDate(o.received_at) === state.ordersDate);\n    summaryText = `Предоплаты за ${formatReceiptDay(state.ordersDate)}: ${list.length}`;\n    renderOrdersCalendar();\n  } else {\n    const mk = monthKeyOf(todayMsk());\n    state.ordersMonth = mk;\n    list = list.filter(o => monthKeyOf(mskDate(o.received_at)) === mk);\n    summaryText = list.length\n      ? `Ближайшие: ${list.length} за ${monthTitle(mk).toLowerCase()}`\n      : `За ${monthTitle(mk).toLowerCase()} предоплат пока нет`;\n    renderOrdersCalendar();\n  }\n\n  summary.textContent = summaryText;\n\n  if (!list.length) {\n    box.innerHTML = state.ordersFilter === "date" ? `<div class="empty">Заказов не найдено</div>` : "";\n    return;\n  }\n\n  box.innerHTML = list.map(orderCard).join("");\n  box.querySelectorAll(".card").forEach(card => {\n    card.addEventListener("click", () => {\n      const o = state.orders.find(x => String(x.order_id) === card.dataset.id);\n      if (o) openDetail(o); // карточка заказа (как в расписании), не карточка клиента\n    });\n  });\n}\n\nfunction renderClients() {\n  const box = document.getElementById("clientsList");\n  const summary = document.getElementById("clientsSummary");\n  const clients = state.clients;\n  if (!clients.length) {\n    box.innerHTML = `<div class="empty">Клиентов нет</div>`;\n    summary.textContent = "Клиентов нет";\n    return;\n  }\n  summary.textContent = `Клиентов: ${clients.length}`;\n  box.innerHTML = clients.map(c => `\n    <article class="card" data-cid="${esc(c.client_id)}">\n      <div class="card-mainline"><div class="name">${esc(c.name || "Без имени")}</div></div>\n      <div class="meta">📞 ${esc(c.phone || "—")} · заказов: ${esc(c.orders_count ?? 0)} · звонков: ${esc(c.calls_count ?? 0)}</div>\n      ${c.last_call_at ? `<div class="meta">🕒 Последний звонок: ${esc(formatCallDatetime(c.last_call_at))}</div>` : ""}\n    </article>\n  `).join("");\n  box.querySelectorAll(".card").forEach(card => {\n    card.addEventListener("click", () => openClientCard(card.dataset.cid));\n  });\n}\n\nfunction callsDateLabel() {\n  const todayIso = isoDate(new Date());\n  return state.callsDate === todayIso ? "сегодня" : (formatEventDate(state.callsDate) || state.callsDate);\n}\n\nfunction renderCallsToday() {\n  const box = document.getElementById("callsTodayList");\n  const summary = document.getElementById("callsSummary");\n  const calls = state.callsToday || [];\n  const label = callsDateLabel();\n  if (!calls.length) {\n    summary.textContent = `Звонков за ${label}: 0`;\n    box.innerHTML = `<div class="empty">Звонков за ${label} нет</div>`;\n    return;\n  }\n  summary.textContent = `Звонков за ${label}: ${calls.length}`;\n  box.innerHTML = calls.map((c, i) => callCard(c, { showClient: true, index: i })).join("");\n  initCallCards(box, calls);\n  box.querySelectorAll(".call-card").forEach(card => {\n    card.addEventListener("click", () => {\n      const call = calls[Number(card.dataset.callIndex)];\n      if (!call) return;\n      const info = callClientInfo(call);\n      if (info.client) openClientCard(info.client.client_id);\n      else if (info.order) openDetail(info.order);\n    });\n  });\n}\n\n/* ---------- карточки БСО ---------- */\n\nfunction bsoCard(b) {\n  const pay = Number(b.payment_amount) || 0;\n  const amt = Number(b.order_amount) || 0;\n  const total = Math.round((pay + amt) * 100) / 100;\n  const name = b.order_customer_name || b.customer_name || "Без имени";\n  const nameEl = b.client_id != null\n    ? `<button class="bso-client" type="button" data-client-id="${esc(b.client_id)}">👤 ${esc(name)}</button>`\n    : `<div class="bso-client">👤 ${esc(name)}</div>`;\n  return `\n    <article class="bso-card">\n      <button class="bso-toggle" type="button" aria-expanded="false">\n        <div class="bso-toggle-main">\n          <div class="bso-toggle-title">БСО № ${esc(b.bso_number || "—")}</div>\n          <div class="bso-toggle-date">${esc(formatEventDate(b.game_date) || "—")}</div>\n        </div>\n        <div class="bso-toggle-total">${fmtMoney(total)}</div>\n        <span class="bso-chevron">▾</span>\n      </button>\n      <div class="bso-body" hidden>\n        ${nameEl}\n        <div class="bso-details">\n          <div class="bso-row"><span>Заказ</span><span>${esc(b.order_id || "—")}</span></div>\n          <div class="bso-row"><span>Игроков (факт)</span><span>${esc(b.players_fact ?? "—")}</span></div>\n          <div class="bso-row"><span>Зона отдыха</span><span>${fmtMoney(b.rest_zone_amount)}</span></div>\n        </div>\n        <div class="bso-foot">\n          <div class="bso-row"><span>Бронь</span><span>${fmtMoney(b.payment_amount)}</span></div>\n          <div class="bso-row"><span>Сумма заказа</span><span>${fmtMoney(b.order_amount)}</span></div>\n          <div class="bso-row bso-grand"><span>Итого</span><span>${fmtMoney(pay)} + ${fmtMoney(amt)} = ${fmtMoney(total)}</span></div>\n        </div>\n      </div>\n    </article>\n  `;\n}\n\nfunction renderBsoDateStrip() {\n  const wrap = document.getElementById("bsoDateStrip");\n  if (!wrap) return;\n  if (state.bsoFilter !== "date") {\n    wrap.hidden = true;\n    return;\n  }\n  wrap.hidden = false;\n  function onChange(ds) {\n    state.bsoDate = ds;\n    renderBso();\n  }\n  renderDayStrip(wrap, state.bsoDate, onChange);\n}\n\nfunction renderBso() {\n  const box = document.getElementById("bsoList");\n  const summary = document.getElementById("bsoSummary");\n  renderBsoDateStrip();\n  let list = state.bso;\n  const byDate = state.bsoFilter === "date" && state.bsoDate;\n  if (byDate) {\n    list = list.filter(b => String(b.game_date || "").slice(0, 10) === state.bsoDate);\n  }\n  if (!list.length) {\n    summary.textContent = "БСО нет";\n    box.innerHTML = `<div class="empty">БСО пока нет</div>`;\n    return;\n  }\n  summary.textContent = byDate\n    ? `БСО за ${formatEventDate(state.bsoDate)}: ${list.length}`\n    : `БСО: ${list.length}`;\n  box.innerHTML = list.map(bsoCard).join("");\n  box.querySelectorAll(".bso-toggle").forEach(btn => {\n    btn.addEventListener("click", () => {\n      const card = btn.closest(".bso-card");\n      const body = card.querySelector(".bso-body");\n      const expanded = btn.getAttribute("aria-expanded") === "true";\n      btn.setAttribute("aria-expanded", String(!expanded));\n      body.hidden = expanded;\n    });\n  });\n  box.querySelectorAll(".bso-client[data-client-id]").forEach(btn => {\n    btn.addEventListener("click", () => openClientCard(btn.dataset.clientId));\n  });\n}\n\n/* ---------- навигация ---------- */\n\nfunction show(view) {\n  state.view = view;\n  Object.entries(VIEW_SECTIONS).forEach(([k, id]) => {\n    const el = document.getElementById(id);\n    if (el) el.hidden = (k !== view);\n  });\n  const nav = document.getElementById("bottomNav");\n  nav.hidden = (view === "start");\n  document.querySelectorAll(".nav-item[data-go]").forEach(b => {\n    b.classList.toggle("active", b.dataset.go === view);\n  });\n  const navMore = document.getElementById("navMore");\n  if (navMore) navMore.classList.toggle("active", view === "clients" || view === "bso");\n  const moreMenu = document.getElementById("moreMenu");\n  if (moreMenu) moreMenu.hidden = true;\n\n  if (view === "schedule") renderSchedule();\n  else if (view === "clients") renderClients();\n  else if (view === "orders") renderOrders();\n  else if (view === "calls") { renderCallsScreen(); }\n  else if (view === "bso") renderBso();\n  window.scrollTo(0, 0);\n}\n\n/* ---------- загрузка данных ---------- */\n\nasync function loadClientsData() {\n  const r = await fetch("/api/clients?limit=500", {cache:"no-store", headers: authHeaders()});\n  if (!r.ok) throw new Error("HTTP " + r.status);\n  const data = await r.json();\n  state.clients = data.clients || [];\n}\n\nasync function loadOrdersData() {\n  const r = await fetch("/api/orders?limit=200", {cache:"no-store", headers: authHeaders()});\n  if (!r.ok) throw new Error("HTTP " + r.status);\n  const data = await r.json();\n  state.orders = data.orders || [];\n}\n\nasync function loadBsoData() {\n  const r = await fetch("/api/bso?limit=500", {cache:"no-store", headers: authHeaders()});\n  if (!r.ok) throw new Error("HTTP " + r.status);\n  const data = await r.json();\n  state.bso = data.bso || [];\n}\n\nasync function loadCallsForDate(dateStr) {\n  const box = document.getElementById("callsTodayList");\n  const summary = document.getElementById("callsSummary");\n  summary.textContent = "Загрузка звонков…";\n  box.innerHTML = `<div class="empty">Загрузка звонков…</div>`;\n  try {\n    const q = dateStr ? `?date=${encodeURIComponent(dateStr)}` : "";\n    const r = await fetch(`/api/calls/today${q}`, {cache:"no-store", headers: authHeaders()});\n    if (!r.ok) throw new Error("HTTP " + r.status);\n    const data = await r.json();\n    state.callsToday = data.calls || [];\n    renderCallsToday();\n  } catch (e) {\n    summary.textContent = "Ошибка загрузки";\n    box.innerHTML = `<div class="empty">${esc(e.message)}</div>`;\n  }\n}\n\nfunction renderCallsScreen() {\n  const strip = document.getElementById("callsDateStrip");\n  function onChange(ds) {\n    state.callsDate = ds;\n    renderDayStrip(strip, state.callsDate, onChange);\n    loadCallsForDate(ds);\n  }\n  renderDayStrip(strip, state.callsDate, onChange);\n  loadCallsForDate(state.callsDate);\n}\n\nfunction loadWeekendSummary() {\n  const el = document.getElementById("weekendCount");\n  if (!el) return;\n  try {\n    fetch("/api/summary/weekend", {cache:"no-store", headers: authHeaders()})\n      .then(r => { if (!r.ok) throw new Error("HTTP " + r.status); return r.json(); })\n      .then(data => { el.textContent = Number(data.people || 0).toLocaleString("ru-RU"); })\n      .catch(() => { el.textContent = "—"; });\n  } catch (e) {\n    el.textContent = "—";\n  }\n}\n\nasync function init() {\n  const now = new Date();\n  state.selectedDate = new Date(now.getFullYear(), now.getMonth(), now.getDate());\n  state.callsDate = isoDate(new Date());\n\n  await Promise.all([\n    loadOrdersData().catch(() => {}),\n    loadClientsData().catch(() => {}),\n    loadBsoData().catch(() => {}),\n  ]);\n  loadWeekendSummary();\n\n  if (state.view !== "start") show(state.view);\n}\n\n/* ---------- события ---------- */\n\ndocument.querySelectorAll("[data-go]").forEach(btn => {\n  btn.addEventListener("click", () => show(btn.dataset.go));\n});\n\nconst navMore = document.getElementById("navMore");\nconst moreMenu = document.getElementById("moreMenu");\nif (navMore && moreMenu) {\n  navMore.addEventListener("click", (e) => {\n    e.stopPropagation();\n    moreMenu.hidden = !moreMenu.hidden;\n  });\n  document.addEventListener("click", (e) => {\n    if (!moreMenu.hidden && !moreMenu.contains(e.target) && e.target !== navMore) {\n      moreMenu.hidden = true;\n    }\n  });\n}\n\ndocument.getElementById("prevMonth").addEventListener("click", () => shiftMonth(-1));\ndocument.getElementById("nextMonth").addEventListener("click", () => shiftMonth(1));\n\ndocument.querySelectorAll("#ordersFilterRow .chip").forEach(btn => {\n  btn.addEventListener("click", () => {\n    document.querySelectorAll("#ordersFilterRow .chip").forEach(x => x.classList.remove("active"));\n    btn.classList.add("active");\n    state.ordersFilter = btn.dataset.ofilter;\n    renderOrders();\n  });\n});\n\ndocument.querySelectorAll("#bsoFilterRow .chip").forEach(btn => {\n  btn.addEventListener("click", () => {\n    document.querySelectorAll("#bsoFilterRow .chip").forEach(x => x.classList.remove("active"));\n    btn.classList.add("active");\n    state.bsoFilter = btn.dataset.bsofilter;\n    if (state.bsoFilter === "date" && !state.bsoDate) state.bsoDate = isoDate(new Date());\n    renderBso();\n  });\n});\n\ndocument.getElementById("closeDialog").addEventListener("click", () => dialog.close());\ndialog.addEventListener("click", e => { if (e.target === dialog) dialog.close(); });\n\ninit();\n'

STYLE_CSS = ':root{\n  --bg:#f1f0e9;\n  --card:#ffffff;\n  --text:#242720;\n  --muted:#73776d;\n  --line:#dadbd3;\n  --green:#708f3f;\n  --green-dark:#435c27;\n  --green-soft:#e7eddc;\n  --ease-out:cubic-bezier(.23,1,.32,1);\n}\n*{box-sizing:border-box}\nhtml{-webkit-text-size-adjust:100%;text-size-adjust:100%;\n-webkit-tap-highlight-color:transparent;overscroll-behavior:none}\nbutton,a,[role="button"],.sch-card,.card,.order-mini,.call-card-linked,.more-item,.item-copy{\ntouch-action:manipulation;user-select:none;-webkit-user-select:none;-webkit-touch-callout:none}\n[hidden]{display:none !important}\nbody{margin:0;background:var(--bg);color:var(--text);\nfont-family:-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}\n.app{max-width:720px;margin:auto;\npadding-top:max(18px,env(safe-area-inset-top));\npadding-bottom:96px;\npadding-left:max(14px,env(safe-area-inset-left));\npadding-right:max(14px,env(safe-area-inset-right))}\n.brand{font-size:12px;font-weight:800;letter-spacing:.16em;color:var(--green-dark)}\nh1{font-size:clamp(22px,7vw,30px);margin:4px 0 15px}\n\n/* ---------- стартовый экран ---------- */\n.screen-start{min-height:calc(100vh - 36px);min-height:calc(100svh - 36px);display:flex;flex-direction:column}\n.start-header{padding-top:12px}\n.start-title{font-size:clamp(34px,11vw,44px);margin:2px 0 0;letter-spacing:.02em}\n.start-sub{font-size:13px;color:var(--muted);margin-top:2px}\n.start-grid{display:grid;grid-template-columns:1fr 1fr;gap:14px;margin:auto 0;padding:28px 0}\n.start-btn{display:flex;flex-direction:column;align-items:center;justify-content:center;gap:10px;\naspect-ratio:1;border:1px solid var(--line);background:var(--card);border-radius:20px;\nfont-size:17px;font-weight:700;color:var(--text);cursor:pointer;min-height:44px;\ntransition:transform 110ms var(--ease-out)}\n.start-btn:active{transform:scale(.97)}\n.start-ico{font-size:clamp(28px,9vw,34px);line-height:1}\n.start-btn-wide{grid-column:1 / -1;flex-direction:row;aspect-ratio:auto;min-height:58px;gap:12px;font-size:18px}\n\n/* ---------- шапки экранов ---------- */\n.screen-header{margin-bottom:4px}\n\n/* ---------- период (месяц) ---------- */\n.period-row{display:flex;align-items:center;gap:8px;margin:10px 0 12px;flex-wrap:wrap}\n.month-nav{display:flex;align-items:center;flex:1 1 auto;min-width:0}\n.month-arrow{border:1px solid var(--line);background:var(--card);border-radius:12px;\nfont-size:22px;line-height:1;padding:10px 12px;color:var(--green-dark);min-width:44px;min-height:44px}\n.month-label{flex:1;min-width:0;border:1px solid var(--line);background:var(--card);border-radius:12px;\npadding:11px 10px;font-size:16px;font-weight:700;color:var(--text);white-space:nowrap;\noverflow:hidden;text-overflow:ellipsis}\n.icon-btn{border:1px solid var(--line);background:var(--card);border-radius:12px;\nfont-size:19px;padding:10px 13px;color:var(--muted);min-height:44px}\n.cta-btn{border:0;background:var(--green);color:#fff;border-radius:12px;\nfont-size:15px;font-weight:700;padding:12px 14px;white-space:nowrap;cursor:pointer;flex:0 0 auto;min-height:44px}\n\n/* ---------- неделя (горизонтальный календарь) ---------- */\n.week{display:flex;align-items:stretch;gap:6px;overflow-x:auto;padding-bottom:4px;\noverscroll-behavior-x:contain}\n.week-arrow{border:0;background:none;font-size:24px;color:var(--muted);padding:0;\nflex:0 0 auto;min-width:40px;min-height:44px}\n.week-day{flex:1 1 0;min-width:42px;border:1px solid var(--line);background:var(--card);\nborder-radius:14px;padding:9px 4px 7px;display:flex;flex-direction:column;align-items:center;gap:3px;cursor:pointer}\n.week-dow{font-size:11px;color:var(--muted);text-transform:uppercase}\n.week-num{font-size:clamp(17px,4.5vw,19px);font-weight:800;line-height:1}\n.week-dot{width:6px;height:6px;border-radius:50%}\n.week-dot.has{background:var(--green)}\n.week-day.today .week-num{color:var(--green)}\n.week-day.active{background:var(--green);border-color:var(--green)}\n.week-day.active .week-dow,.week-day.active .week-num{color:#fff}\n.week-day.active .week-dot.has{background:#fff}\n\n/* ---------- информационная панель дня ---------- */\n.day-info{background:var(--card);border:1px solid var(--line);border-radius:16px;\npadding:14px;margin:10px 0;min-height:64px}\n.day-info-title{font-size:16px;font-weight:700}\n.day-info-body{font-size:13px;color:var(--muted);margin-top:5px}\n\n/* сводка дня: игры и игроки */\n.day-stats{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-top:11px}\n.day-stat{display:flex;align-items:baseline;gap:7px;background:var(--bg);\nborder-radius:12px;padding:10px 12px}\n.day-stat-ico{font-size:16px;line-height:1}\n.day-stat-num{font-size:26px;font-weight:800;color:var(--green-dark);line-height:1}\n.day-stat-cap{font-size:13px;color:var(--muted)}\n\n/* ---------- список расписания ---------- */\n.schedule-list{display:grid;gap:10px}\n.sch-card{border:1px solid var(--line);border-radius:16px;padding:14px 14px 12px;\nbackground:var(--card);border-left:5px solid #9aa08f;cursor:pointer;\ntransition:transform 110ms var(--ease-out)}\n.sch-card:active{transform:scale(.98)}\n.sch-row1{display:flex;align-items:baseline;gap:8px 10px;flex-wrap:wrap}\n.sch-period{font-size:clamp(16px,5vw,20px);font-weight:800;color:var(--green-dark);flex:0 0 auto}\n.sch-game{flex:1 1 auto;min-width:0;font-size:clamp(15px,4.2vw,17px);font-weight:700;line-height:1.2}\n.sch-price{font-size:clamp(15px,4.2vw,17px);font-weight:750;white-space:nowrap;margin-left:auto}\n.sch-row2{display:flex;align-items:center;gap:8px;margin-top:7px}\n.sch-qty{font-size:14px;font-weight:650;white-space:nowrap}\n.sch-name{flex:1;min-width:0;font-size:15px;color:var(--text)}\n.sch-phone{text-decoration:none;font-size:15px;flex:0 0 auto}\n.sch-row3{font-size:12px;color:var(--muted);margin-top:6px}\n\n/* цветовая маркировка типов игр (приглушённые тона) */\n.card-paintball{background:#eef4e6;border-color:#cddcc0;border-left-color:#6f9a3f}\n.card-lasertag{background:#f7f1de;border-color:#e6d7a8;border-left-color:#b9962c}\n.card-kidball{background:#f7e8e5;border-color:#e6c4be;border-left-color:#bd5a4c}\n.card-other{background:var(--card);border-left-color:#9aa08f}\n\n/* ---------- фильтры-чипы (Заказы) ---------- */\n.filter-row{display:flex;gap:8px;margin:6px 0 10px;flex-wrap:wrap}\n.chip{border:1px solid var(--line);background:var(--card);border-radius:999px;\npadding:8px 14px;font-size:14px;cursor:pointer;min-height:38px}\n.chip.active{background:var(--green);border-color:var(--green);color:#fff}\n\n/* ---------- фильтр-полоса дат (ползунок) ---------- */\n.day-strip-wrap{margin:10px 0}\n.day-strip{display:flex;gap:6px;overflow-x:auto;padding:2px 2px 6px;-webkit-overflow-scrolling:touch;\noverscroll-behavior-x:contain}\n.day-chip{flex:0 0 auto;min-width:54px;border:1px solid var(--line);background:var(--card);border-radius:12px;\n  padding:8px 6px 7px;display:flex;flex-direction:column;align-items:center;gap:3px;cursor:pointer;min-height:44px}\n.day-chip-dow{font-size:10px;color:var(--muted);text-transform:uppercase}\n.day-chip-num{font-size:15px;font-weight:700;line-height:1}\n.day-chip.today .day-chip-num{color:var(--green)}\n.day-chip.active{background:var(--green);border-color:var(--green)}\n.day-chip.active .day-chip-dow,.day-chip.active .day-chip-num{color:#fff}\n.day-chip.all{min-width:auto;font-size:14px;font-weight:700;padding:8px 14px}\n/* даты поступлений (экран «Заказы»): подпись месяца и число поступлений на чипе */\n.strip-month{flex:0 0 auto;align-self:center;padding:0 2px 0 6px;font-size:10px;font-weight:700;color:var(--muted);text-transform:uppercase;letter-spacing:.04em}\n.day-chip-cnt{font-size:9px;color:var(--muted);line-height:1}\n.day-chip.active .day-chip-cnt{color:#fff}\n\n/* ---------- нижняя навигация ---------- */\n.bottom-nav{position:fixed;left:0;right:0;bottom:0;margin:0 auto;max-width:720px;\ndisplay:grid;grid-template-columns:repeat(4,1fr);\nbackground:#ffffff;border-top:1px solid var(--line);\npadding:8px max(6px,env(safe-area-inset-left)) calc(8px + env(safe-area-inset-bottom)) max(6px,env(safe-area-inset-right))}\n.nav-item{display:flex;flex-direction:column;align-items:center;gap:3px;\nborder:0;background:none;font-size:11px;color:var(--muted);cursor:pointer;min-height:44px}\n.nav-ico{font-size:22px;line-height:1}\n.nav-item.active{color:var(--green-dark)}\n.nav-item.active .nav-ico{filter:none}\n\n/* ---------- общие карточки (Заказы/Клиенты) ---------- */\n.summary{font-size:13px;color:var(--muted);margin:12px 2px}\n.orders{display:grid;gap:10px}\n.card{background:var(--card);border:1px solid var(--line);border-radius:17px;padding:15px;\ntransition:transform 110ms var(--ease-out)}\n.card:active{transform:scale(.98)}\n.topline{display:flex;justify-content:space-between;align-items:flex-start;gap:10px}\n.card-mainline{display:flex;justify-content:space-between;align-items:center;gap:10px;margin-top:6px}\n.players-count{font-size:23px;font-weight:800;line-height:1;text-align:right;white-space:nowrap}\n.players-count span{font-size:26px}\n.name{font-size:clamp(16px,4.5vw,18px);font-weight:700;min-width:0}\n.status{font-size:11px;padding:5px 8px;border-radius:999px;background:var(--green-soft);color:var(--green-dark);white-space:nowrap}\n.date{font-weight:650;margin-top:10px}\n.meta{color:var(--muted);font-size:14px;margin-top:5px;line-height:1.45}\n.received-at{color:#8a8d84;font-size:12px;font-style:italic;margin-top:7px;line-height:1.35}\n.game{font-weight:650;margin-top:9px}\n.price{font-size:18px;font-weight:750;margin-top:10px}\n.empty{text-align:center;color:var(--muted);padding:45px 10px}\n\n/* ---------- диалог заказа ---------- */\ndialog{border:0;border-radius:18px;padding:0;width:min(680px,calc(100% - 22px))}\ndialog::backdrop{background:rgba(0,0,0,.45)}\n.dialog-body{background:var(--card);padding:22px;position:relative}\n.close{position:absolute;right:12px;top:10px;border:0;background:none;font-size:30px;color:var(--muted)}\n.detail-title{font-size:24px;font-weight:750;padding-right:30px}\n.detail-status{margin:9px 0 18px}\n.detail-status{display:flex;align-items:center;gap:9px;flex-wrap:wrap}\n.amount-pill{font-size:14px;font-weight:700;padding:6px 11px;border-radius:999px;background:var(--green-soft);color:var(--green-dark);white-space:nowrap}\n.txn-id{font-size:12px;color:#b3b4a9;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.sum-pill{font-size:13px;font-weight:700;padding:5px 9px;border-radius:999px;background:var(--green-soft);color:var(--green-dark);white-space:nowrap}\n.key-block{background:var(--bg);border-radius:14px;padding:14px 15px;display:grid;gap:12px;margin-bottom:9px}\n.key-label{font-size:11px;color:var(--muted)}\n.key-value{font-size:20px;font-weight:650;line-height:1.25;margin-top:3px}\n.key-qty{font-size:32px;font-weight:800;line-height:1.05;margin-top:2px}\n.item-copy{position:relative;cursor:pointer}\n.item-copy:active{background:var(--green-soft)}\nbutton.action.action-ghost{background:#fff;color:var(--green-dark);border:1px solid var(--line)}\n.copy-toast{position:fixed;left:50%;bottom:26px;transform:translateX(-50%);background:#242720;color:#fff;font-size:13px;padding:9px 14px;border-radius:10px;opacity:0;transition:opacity .18s;pointer-events:none;z-index:99}\n.copy-toast.on{opacity:.94}\n.grid{display:grid;grid-template-columns:1fr 1fr;gap:9px}\n.item{background:var(--bg);border-radius:12px;padding:11px}\n.label{font-size:11px;color:var(--muted)}\n.value{font-size:15px;margin-top:3px}\n.actions{display:grid;gap:8px;margin-top:15px}\n.action{display:block;text-align:center;text-decoration:none;background:var(--green);color:#fff;border-radius:12px;padding:12px}\nbutton.action{border:0;cursor:pointer;font:inherit;width:100%}\n@media(max-width:430px){.grid{grid-template-columns:1fr}}\n\n.calls-section{margin-top:18px}\n.calls-heading{font-size:18px;font-weight:700;margin-bottom:10px}\n.calls-list{display:grid;gap:10px}\n.call-card{padding:12px;border-radius:14px;background:rgba(127,127,127,0.08)}\n.call-tags{display:flex;flex-wrap:wrap;align-items:center;gap:7px;margin-bottom:8px}\n.call-tag{font-size:12px;font-weight:650;padding:3px 10px;border-radius:999px;border:1px solid transparent;white-space:nowrap}\n.call-tag-meta{font-size:12px;color:var(--muted);white-space:nowrap}\n.call-tag.tag-kids{background:#e8f1ff;color:#1c4b8a;border-color:#cadcf6}\n.call-tag.tag-school{background:#efe8ff;color:#4a2a8a;border-color:#dcd0f7}\n.call-tag.tag-corp{background:#e6f4ea;color:#1e6b3a;border-color:#c8e5d3}\n.call-tag.tag-party{background:#fdf1e3;color:#8a5a12;border-color:#f2ddc0}\n.call-tag.tag-game{background:#eef4f8;color:#2c5a73;border-color:#d6e4ec}\n.call-tag.tag-junk,.call-tag.tag-unknown{background:#f1efec;color:#7d7972;border-color:#e2ded8}\n.call-topline{display:flex;justify-content:space-between;gap:10px;align-items:center}\n.call-date{font-weight:600}\n.call-duration{white-space:nowrap;font-variant-numeric:tabular-nums}\n.call-admin,.call-phone{margin-top:5px;opacity:.8;font-size:14px}\n.call-audio{width:100%;margin-top:10px}\n.call-link{margin-top:8px;background:none;border:1px solid var(--line);color:var(--green-dark);font:inherit;font-size:13px;padding:7px 12px;border-radius:10px;cursor:pointer}\n.call-link:active{background:var(--green-soft)}\n.call-unavailable{margin-top:10px;opacity:.65;font-size:13px}\n.call-client{font-weight:650;color:var(--green-dark);margin-top:6px}\n.call-card-linked{cursor:pointer;transition:transform 110ms var(--ease-out)}\n.call-card-linked:active{transform:scale(.98)}\n.detail-subtitle{font-size:15px;color:var(--muted);margin-top:4px;padding-right:30px}\n.orders-mini{display:grid;gap:8px}\n.order-mini{padding:10px 12px;border:1px solid var(--line);border-radius:12px;cursor:pointer;\ntransition:transform 110ms var(--ease-out)}\n.order-mini:active{transform:scale(.98)}\n.order-mini-top{display:flex;justify-content:space-between;gap:10px}\n.order-mini-id{font-weight:700}\n.order-mini-date{color:var(--muted);white-space:nowrap}\n\n/* ---------- отклик на нажатие у элементов, где его не было (29.09.2026) ---------- */\n.chip,.cta-btn,.month-arrow,.icon-btn,.month-label,.nav-item,.more-item{\ntransition:background 110ms var(--ease-out),color 110ms var(--ease-out)}\n.chip:active,.month-arrow:active,.icon-btn:active,.month-label:active{background:var(--green-soft)}\n.cta-btn:active{background:var(--green-dark)}\n.nav-item:active{color:var(--green-dark)}\n\n/* ---------- уменьшенное движение: убираем только движение, не обратную связь ---------- */\n@media (prefers-reduced-motion: reduce){\n  .sch-card,.card,.start-btn,.call-card-linked,.order-mini,.bso-chevron{transition:none}\n  .sch-card:active,.card:active,.start-btn:active,.call-card-linked:active,.order-mini:active{transform:none}\n  .copy-toast{transition-duration:60ms}\n}\n\n.header-row{display:flex;justify-content:space-between;align-items:flex-start;gap:10px}\n.weekend{text-align:right;background:var(--card);border:1px solid var(--line);border-radius:12px;padding:8px 12px}\n.weekend-label{font-size:11px;color:var(--muted);white-space:nowrap}\n.weekend-value{font-size:22px;font-weight:800;color:var(--green-dark);line-height:1.2;margin-top:3px;white-space:nowrap}\n.client-id{font-size:12px;font-weight:400;color:var(--muted);opacity:.65;margin-left:6px;white-space:nowrap}\n\n/* ---------- меню «ЕЩЕ» ---------- */\n.more-menu{position:fixed;right:max(8px,env(safe-area-inset-right));\n bottom:calc(74px + env(safe-area-inset-bottom));\n background:#fff;border:1px solid var(--line);border-radius:14px;\n box-shadow:0 8px 28px rgba(0,0,0,.14);padding:6px;display:flex;flex-direction:column;\n min-width:168px;z-index:60}\n.more-item{display:flex;align-items:center;gap:10px;border:0;background:none;\n padding:12px 14px;font-size:16px;font-weight:650;color:var(--text);cursor:pointer;\n border-radius:10px;text-align:left}\n.more-item:active{background:var(--green-soft)}\n.more-ico{font-size:20px}\n\n/* ---------- карточки БСО ---------- */\n.bso-card{background:var(--card);border:1px solid var(--line);border-radius:18px;padding:16px}\n.bso-client{display:block;border:0;background:none;padding:0;font-size:clamp(16px,4.5vw,18px);\n font-weight:700;color:var(--green-dark);cursor:pointer;text-align:left;margin-bottom:10px}\n.bso-client:not(button){color:var(--text);cursor:default}\n.bso-head{display:flex;flex-direction:column;gap:4px;border-top:1px solid var(--line);padding-top:12px}\n.bso-number{font-size:clamp(22px,6.5vw,28px);font-weight:800;color:var(--text)}\n.bso-date{font-size:15px;color:var(--muted)}\n.bso-total{font-size:clamp(20px,6vw,24px);font-weight:800;color:var(--green-dark)}\n.bso-details{margin-top:12px;border-top:1px dashed var(--line);padding-top:10px;display:grid;gap:6px}\n.bso-row{display:flex;justify-content:space-between;gap:10px;font-size:15px}\n.bso-row span:first-child{color:var(--muted)}\n.bso-row span:last-child{font-weight:650;text-align:right}\n.bso-foot{margin-top:12px;border-top:1px solid var(--line);padding-top:10px;display:grid;gap:6px}\n.bso-grand{font-size:16px;font-weight:800;color:var(--green-dark);border-top:1px dashed var(--line);padding-top:8px;margin-top:4px}\n\n/* ---------- аккордеон БСО (свёрнутая карточка) ---------- */\n.bso-toggle{display:flex;align-items:center;gap:12px;width:100%;border:0;background:none;padding:0;text-align:left;cursor:pointer;min-height:44px}\n.bso-toggle-main{flex:1;min-width:0;display:flex;flex-direction:column;gap:3px}\n.bso-toggle-title{font-size:clamp(22px,6.5vw,28px);font-weight:800;color:var(--text);line-height:1.1}\n.bso-toggle-date{font-size:13px;color:var(--muted)}\n.bso-toggle-total{font-size:clamp(18px,5.5vw,22px);font-weight:800;color:var(--green-dark);white-space:nowrap}\n.bso-chevron{flex:0 0 auto;font-size:16px;color:var(--muted);transition:transform .16s ease}\n.bso-toggle[aria-expanded="true"] .bso-chevron{transform:rotate(180deg)}\n.bso-body{margin-top:14px;padding-top:12px;border-top:1px solid var(--line)}\n\n/* ---------- адаптивность (разные телефоны) ---------- */\n@media(max-width:400px){\n  .period-row{gap:8px}\n  .month-nav{flex:1 1 100%;order:1}\n  .icon-btn{order:2}\n  .cta-btn{order:3;flex:1 1 auto}\n}\n@media(max-width:380px){\n  .app{\n    padding-top:max(12px,env(safe-area-inset-top));\n    padding-bottom:86px;\n    padding-left:max(10px,env(safe-area-inset-left));\n    padding-right:max(10px,env(safe-area-inset-right));\n  }\n  .start-grid{gap:10px;padding:18px 0}\n  .start-btn{gap:8px;font-size:16px}\n  .sch-card{padding:12px 12px 10px}\n  .players-count{font-size:20px}\n  .players-count span{font-size:22px}\n}\n\n/* календарь «Найти по дате» (экран «Заказы») — дни с предоплатами помечены точкой */\n.cal-wrap{margin:10px 0 4px}\n.cal-head{display:flex;align-items:center;margin-bottom:8px}\n.cal-dow{display:grid;grid-template-columns:repeat(7,1fr);gap:4px;margin-bottom:4px}\n.cal-dow span{font-size:10px;color:var(--muted);text-transform:uppercase;text-align:center}\n.cal-grid{display:grid;grid-template-columns:repeat(7,1fr);gap:4px}\n.cal-day{position:relative;display:flex;flex-direction:column;align-items:center;justify-content:center;\n min-height:44px;border:1px solid var(--line);background:var(--card);border-radius:12px;padding:4px 0 6px;\n font-size:15px;font-weight:700;color:var(--text)}\n.cal-day.off{border-color:transparent;background:transparent;color:#c9cabf;font-weight:500}\n.cal-day.empty{min-height:44px}\n.cal-day.today .cal-num{color:var(--green)}\n.cal-day.active{background:var(--green);border-color:var(--green)}\n.cal-day.active .cal-num{color:#fff}\n.month-arrow:disabled{opacity:.35}\n.cal-dot{width:6px;height:6px;border-radius:50%;margin-top:2px;background:transparent}\n.cal-dot.has{background:var(--green)}\n.cal-day.active .cal-dot.has{background:#fff}\n/* БСО в карточке заказа: блок появляется сам, когда бланк заведён */\n.bso-inline{background:var(--bg);border:1px solid var(--line);border-radius:14px;padding:12px;display:grid;gap:6px}\n.bso-inline-head{display:flex;align-items:baseline;justify-content:space-between;gap:10px;padding-bottom:7px;border-bottom:1px dashed var(--line)}\n.bso-inline-num{font-size:16px;font-weight:700;color:var(--text)}\n.bso-inline-sum{font-size:19px;font-weight:800;color:var(--green-dark);white-space:nowrap}\n'
